def test_known_values():
    codes, scale = solution.quantize_int8([0.0, 127.0, -127.0])
    assert scale == 1.0 and codes == [0, 127, -127]

def test_peak_scale():
    codes, scale = solution.quantize_int8([-0.5, 0.2])
    assert abs(scale - 0.5 / 127) < 1e-15
    assert codes[0] == -127

def test_all_zero():
    assert solution.quantize_int8([0.0, 0.0]) == ([0, 0], 0.0)

def test_error_bound():
    w = [-0.9, -0.3, 0.0, 0.45, 1.2]
    codes, scale = solution.quantize_int8(w)
    for original, q in zip(w, codes):
        assert abs(original - q * scale) <= scale / 2 + 1e-12

def test_empty():
    try:
        solution.quantize_int8([])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_no_mutation():
    w = [0.1, -0.2, 0.3]
    solution.quantize_int8(w)
    assert w == [0.1, -0.2, 0.3]

def test_clamped():
    codes, scale = solution.quantize_int8([1.2, -1.2])
    assert codes == [127, -127]
    assert scale > 0
